CREATE TABLE input (id INTEGER PRIMARY KEY, text TEXT, run INTEGER);
CREATE TABLE third (id INTEGER PRIMARY KEY, text TEXT, run INTEGER);
CREATE TABLE secondary (id INTEGER PRIMARY KEY, run INTEGER, cell INTEGER, gate INTEGER, about INTEGER, text TEXT, made INTEGER);
CREATE TABLE out_mother (id INTEGER PRIMARY KEY, run INTEGER, cell INTEGER, gate INTEGER, at INTEGER, text TEXT);
CREATE TABLE out_user (id INTEGER PRIMARY KEY, run INTEGER, cell INTEGER, value TEXT);
CREATE TABLE run (id INTEGER PRIMARY KEY, arrival INTEGER, parent INTEGER, root INTEGER, kind INTEGER, cell INTEGER, about INTEGER, at INTEGER, moment INTEGER);
CREATE INDEX run_parent ON run (parent);
CREATE INDEX run_root ON run (root);
CREATE TABLE seq (run INTEGER, pos INTEGER, gate INTEGER, PRIMARY KEY (run, pos));
CREATE TABLE run_memory (run INTEGER PRIMARY KEY, input TEXT NOT NULL, source TEXT NOT NULL, gate INTEGER, shard INTEGER, at INTEGER);
CREATE TABLE run_sheet (run INTEGER REFERENCES run_memory(run), cell INTEGER, state INTEGER NOT NULL DEFAULT 0 CHECK (state IN (0, 1)), value TEXT, PRIMARY KEY (run, cell));
CREATE TABLE run_receipt (id INTEGER PRIMARY KEY, run INTEGER, pos INTEGER, gate INTEGER, shard INTEGER);
CREATE INDEX receipt_run ON run_receipt (run);
CREATE TABLE timeline (id INTEGER PRIMARY KEY, at INTEGER, run INTEGER, key1 INTEGER, key2 INTEGER);
CREATE TABLE complete (run INTEGER PRIMARY KEY);
CREATE TABLE hop (id INTEGER PRIMARY KEY, text TEXT, p1, p2, p3, p4, p5, p6);
CREATE TABLE land (id INTEGER PRIMARY KEY, run INTEGER, pos INTEGER, gate INTEGER, before INTEGER, next INTEGER, via INTEGER NOT NULL DEFAULT 0);
CREATE TABLE refused (id INTEGER PRIMARY KEY, text TEXT, error TEXT);
CREATE TABLE hit (id INTEGER PRIMARY KEY, run INTEGER, pos INTEGER, gate INTEGER, before INTEGER, next INTEGER, via INTEGER, had INTEGER, shard INTEGER, call INTEGER, spawn INTEGER);
CREATE TABLE replay (id INTEGER PRIMARY KEY, parent INTEGER, source INTEGER, kind INTEGER);
CREATE TABLE ended (id INTEGER PRIMARY KEY, run INTEGER, gate INTEGER, shard INTEGER);
CREATE TABLE build_span (run INTEGER PRIMARY KEY, pos INTEGER);
