CREATE TRIGGER input_go AFTER INSERT ON input BEGIN
  UPDATE clock SET n = n + 1; INSERT INTO run (arrival, parent, root, kind, cell, about, at, moment) VALUES (1, NULL, NULL, 0, NULL, NULL, (SELECT n FROM clock), strftime('%s', 'now')); UPDATE run SET root = coalesce((SELECT root FROM run WHERE id = NULL), id) WHERE id = (SELECT max(id) FROM run); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) VALUES ((SELECT max(id) FROM run), 19, 1, (SELECT max(id) FROM run)); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT (SELECT max(id) FROM run), 20, 1, NULL WHERE NULL IS NOT NULL;
  UPDATE input SET run = (SELECT max(id) FROM run), text = NULL WHERE id = NEW.id;
  INSERT INTO label (symbol) SELECT s FROM (WITH RECURSIVE ch(i, c) AS (SELECT 1, substr(NEW.text, 1, 1) WHERE NEW.text <> '' UNION ALL SELECT i + 1, substr(NEW.text, i + 1, 1) FROM ch WHERE i < length(NEW.text)), m AS (SELECT i, c, (c GLOB '[A-Za-z_]') AS w FROM ch), st AS (SELECT i, c, w, CASE WHEN w = 0 OR i = 1 OR lag(w) OVER (ORDER BY i) = 0 THEN 1 ELSE 0 END AS start FROM m), sym AS (SELECT i, c, sum(start) OVER (ORDER BY i ROWS UNBOUNDED PRECEDING) AS n FROM st) SELECT n, group_concat(c, '') AS s FROM (SELECT * FROM sym ORDER BY i) GROUP BY n ORDER BY n) WHERE s NOT IN (SELECT symbol FROM label) GROUP BY s ORDER BY min(n); INSERT INTO seq (run, pos, gate) SELECT (SELECT max(id) FROM run), n, (SELECT gate FROM label WHERE symbol = s) FROM (WITH RECURSIVE ch(i, c) AS (SELECT 1, substr(NEW.text, 1, 1) WHERE NEW.text <> '' UNION ALL SELECT i + 1, substr(NEW.text, i + 1, 1) FROM ch WHERE i < length(NEW.text)), m AS (SELECT i, c, (c GLOB '[A-Za-z_]') AS w FROM ch), st AS (SELECT i, c, w, CASE WHEN w = 0 OR i = 1 OR lag(w) OVER (ORDER BY i) = 0 THEN 1 ELSE 0 END AS start FROM m), sym AS (SELECT i, c, sum(start) OVER (ORDER BY i ROWS UNBOUNDED PRECEDING) AS n FROM st) SELECT n, group_concat(c, '') AS s FROM (SELECT * FROM sym ORDER BY i) GROUP BY n ORDER BY n); INSERT INTO land (run, pos, gate, before, next, via) SELECT (SELECT max(id) FROM run), 0, (SELECT arrival FROM run WHERE id = (SELECT max(id) FROM run)), NULL, (SELECT gate FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1), 0 WHERE EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1);
END;
CREATE TRIGGER third_go AFTER INSERT ON third BEGIN
  UPDATE clock SET n = n + 1; INSERT INTO run (arrival, parent, root, kind, cell, about, at, moment) VALUES (5, NULL, NULL, 0, NULL, NULL, (SELECT n FROM clock), strftime('%s', 'now')); UPDATE run SET root = coalesce((SELECT root FROM run WHERE id = NULL), id) WHERE id = (SELECT max(id) FROM run); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) VALUES ((SELECT max(id) FROM run), 19, 1, (SELECT max(id) FROM run)); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT (SELECT max(id) FROM run), 20, 1, NULL WHERE NULL IS NOT NULL;
  UPDATE third SET run = (SELECT max(id) FROM run), text = NULL WHERE id = NEW.id;
  INSERT INTO label (symbol) SELECT s FROM (WITH RECURSIVE ch(i, c) AS (SELECT 1, substr(NEW.text, 1, 1) WHERE NEW.text <> '' UNION ALL SELECT i + 1, substr(NEW.text, i + 1, 1) FROM ch WHERE i < length(NEW.text)), m AS (SELECT i, c, (c GLOB '[A-Za-z_]') AS w FROM ch), st AS (SELECT i, c, w, CASE WHEN w = 0 OR i = 1 OR lag(w) OVER (ORDER BY i) = 0 THEN 1 ELSE 0 END AS start FROM m), sym AS (SELECT i, c, sum(start) OVER (ORDER BY i ROWS UNBOUNDED PRECEDING) AS n FROM st) SELECT n, group_concat(c, '') AS s FROM (SELECT * FROM sym ORDER BY i) GROUP BY n ORDER BY n) WHERE s NOT IN (SELECT symbol FROM label) GROUP BY s ORDER BY min(n); INSERT INTO seq (run, pos, gate) SELECT (SELECT max(id) FROM run), n, (SELECT gate FROM label WHERE symbol = s) FROM (WITH RECURSIVE ch(i, c) AS (SELECT 1, substr(NEW.text, 1, 1) WHERE NEW.text <> '' UNION ALL SELECT i + 1, substr(NEW.text, i + 1, 1) FROM ch WHERE i < length(NEW.text)), m AS (SELECT i, c, (c GLOB '[A-Za-z_]') AS w FROM ch), st AS (SELECT i, c, w, CASE WHEN w = 0 OR i = 1 OR lag(w) OVER (ORDER BY i) = 0 THEN 1 ELSE 0 END AS start FROM m), sym AS (SELECT i, c, sum(start) OVER (ORDER BY i ROWS UNBOUNDED PRECEDING) AS n FROM st) SELECT n, group_concat(c, '') AS s FROM (SELECT * FROM sym ORDER BY i) GROUP BY n ORDER BY n); INSERT INTO land (run, pos, gate, before, next, via) SELECT (SELECT max(id) FROM run), 0, (SELECT arrival FROM run WHERE id = (SELECT max(id) FROM run)), NULL, (SELECT gate FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1), 0 WHERE EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1);
END;
CREATE TRIGGER secondary_go AFTER INSERT ON secondary BEGIN
  UPDATE clock SET n = n + 1; INSERT INTO run (arrival, parent, root, kind, cell, about, at, moment) VALUES (NEW.gate, NEW.run, NULL, 3, NEW.cell, NEW.about, (SELECT n FROM clock), strftime('%s', 'now')); UPDATE run SET root = coalesce((SELECT root FROM run WHERE id = NEW.run), id) WHERE id = (SELECT max(id) FROM run); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) VALUES ((SELECT max(id) FROM run), 19, 1, (SELECT max(id) FROM run)); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT (SELECT max(id) FROM run), 20, 1, NEW.run WHERE NEW.run IS NOT NULL;
  UPDATE secondary SET made = (SELECT max(id) FROM run), text = NULL WHERE id = NEW.id;
  INSERT INTO label (symbol) SELECT s FROM (WITH RECURSIVE ch(i, c) AS (SELECT 1, substr(NEW.text, 1, 1) WHERE NEW.text <> '' UNION ALL SELECT i + 1, substr(NEW.text, i + 1, 1) FROM ch WHERE i < length(NEW.text)), m AS (SELECT i, c, (c GLOB '[A-Za-z_]') AS w FROM ch), st AS (SELECT i, c, w, CASE WHEN w = 0 OR i = 1 OR lag(w) OVER (ORDER BY i) = 0 THEN 1 ELSE 0 END AS start FROM m), sym AS (SELECT i, c, sum(start) OVER (ORDER BY i ROWS UNBOUNDED PRECEDING) AS n FROM st) SELECT n, group_concat(c, '') AS s FROM (SELECT * FROM sym ORDER BY i) GROUP BY n ORDER BY n) WHERE s NOT IN (SELECT symbol FROM label) GROUP BY s ORDER BY min(n); INSERT INTO seq (run, pos, gate) SELECT (SELECT max(id) FROM run), n, (SELECT gate FROM label WHERE symbol = s) FROM (WITH RECURSIVE ch(i, c) AS (SELECT 1, substr(NEW.text, 1, 1) WHERE NEW.text <> '' UNION ALL SELECT i + 1, substr(NEW.text, i + 1, 1) FROM ch WHERE i < length(NEW.text)), m AS (SELECT i, c, (c GLOB '[A-Za-z_]') AS w FROM ch), st AS (SELECT i, c, w, CASE WHEN w = 0 OR i = 1 OR lag(w) OVER (ORDER BY i) = 0 THEN 1 ELSE 0 END AS start FROM m), sym AS (SELECT i, c, sum(start) OVER (ORDER BY i ROWS UNBOUNDED PRECEDING) AS n FROM st) SELECT n, group_concat(c, '') AS s FROM (SELECT * FROM sym ORDER BY i) GROUP BY n ORDER BY n); INSERT INTO land (run, pos, gate, before, next, via) SELECT (SELECT max(id) FROM run), 0, (SELECT arrival FROM run WHERE id = (SELECT max(id) FROM run)), NULL, (SELECT gate FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1), 0 WHERE EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1);
END;
CREATE TRIGGER replay_go AFTER INSERT ON replay BEGIN
  UPDATE clock SET n = n + 1; INSERT INTO run (arrival, parent, root, kind, cell, about, at, moment) VALUES (2, NEW.parent, NULL, NEW.kind, NULL, NULL, (SELECT n FROM clock), strftime('%s', 'now')); UPDATE run SET root = coalesce((SELECT root FROM run WHERE id = NEW.parent), id) WHERE id = (SELECT max(id) FROM run); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) VALUES ((SELECT max(id) FROM run), 19, 1, (SELECT max(id) FROM run)); INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT (SELECT max(id) FROM run), 20, 1, NEW.parent WHERE NEW.parent IS NOT NULL;
  INSERT INTO seq (run, pos, gate) SELECT (SELECT max(id) FROM run), pos, gate FROM seq WHERE run = NEW.source;
  INSERT INTO hop (text, p1, p2, p3, p4, p5, p6) SELECT 'INSERT INTO main.land (run, pos, gate, before, next, via) VALUES (?, ?, ?, ?, ?, ?)', (SELECT max(id) FROM run), 0, 2, NULL, (SELECT gate FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1), 0 WHERE EXISTS (SELECT 1 FROM seq WHERE run = (SELECT max(id) FROM run) AND pos = 1);
END;
CREATE TRIGGER land_go AFTER INSERT ON land BEGIN
  SELECT mother('INSERT INTO ' || 'main."' || NEW.gate || '"' || ' (shard, before, trigger, times) SELECT n + 1, ?, ?, 0 FROM main.shards WHERE NOT EXISTS (SELECT 1 FROM ' || 'main."' || NEW.gate || '"' || ' WHERE before IS ? AND trigger IS ?)', (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE coalesce((SELECT gate FROM seq WHERE run = NEW.run AND pos < NEW.pos AND gate <> 3 ORDER BY pos DESC LIMIT 1), (SELECT arrival FROM run WHERE id = NEW.run)) END), (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE (SELECT gate FROM seq WHERE run = NEW.run AND pos > NEW.pos AND gate <> 3 ORDER BY pos LIMIT 1) END), (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE coalesce((SELECT gate FROM seq WHERE run = NEW.run AND pos < NEW.pos AND gate <> 3 ORDER BY pos DESC LIMIT 1), (SELECT arrival FROM run WHERE id = NEW.run)) END), (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE (SELECT gate FROM seq WHERE run = NEW.run AND pos > NEW.pos AND gate <> 3 ORDER BY pos LIMIT 1) END));
  SELECT mother('UPDATE main.shards SET n = n + 1 WHERE EXISTS (SELECT 1 FROM ' || 'main."' || NEW.gate || '"' || ' WHERE shard = n + 1)');
  SELECT mother('UPDATE ' || 'main."' || NEW.gate || '"' || ' SET times = times + 1 WHERE before IS ? AND trigger IS ?', (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE coalesce((SELECT gate FROM seq WHERE run = NEW.run AND pos < NEW.pos AND gate <> 3 ORDER BY pos DESC LIMIT 1), (SELECT arrival FROM run WHERE id = NEW.run)) END), (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE (SELECT gate FROM seq WHERE run = NEW.run AND pos > NEW.pos AND gate <> 3 ORDER BY pos LIMIT 1) END));
  SELECT mother('INSERT INTO main.hit (run, pos, gate, before, next, via, had, shard, call, spawn) SELECT ?, ?, ?, ?, ?, ?, ?, shard, call, spawn FROM ' || 'main."' || NEW.gate || '"' || ' WHERE before IS ? AND trigger IS ?', NEW.run, NEW.pos, NEW.gate, NEW.before, NEW.next, NEW.via, (CASE WHEN NEW.next IS NULL THEN 0 WHEN EXISTS (SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = CAST(NEW.next AS TEXT)) THEN 1 ELSE 0 END), (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE coalesce((SELECT gate FROM seq WHERE run = NEW.run AND pos < NEW.pos AND gate <> 3 ORDER BY pos DESC LIMIT 1), (SELECT arrival FROM run WHERE id = NEW.run)) END), (CASE WHEN NEW.pos = 0 OR NEW.via = 1 OR NEW.gate = 3 THEN NULL ELSE (SELECT gate FROM seq WHERE run = NEW.run AND pos > NEW.pos AND gate <> 3 ORDER BY pos LIMIT 1) END));
END;
CREATE TRIGGER hit_go AFTER INSERT ON hit BEGIN
  INSERT INTO run_receipt (run, pos, gate, shard) VALUES (NEW.run, NEW.pos, NEW.gate, NEW.shard);
  INSERT INTO hop (text, p1, p2, p3) SELECT 'INSERT INTO main.ended (run, gate, shard) VALUES (?, ?, ?)', NEW.run, NEW.gate, NEW.shard WHERE NEW.next IS NULL AND NEW.via = 0;
  INSERT INTO hop (text, p1, p2, p3, p4, p5, p6) SELECT 'INSERT INTO main.land (run, pos, gate, before, next, via) VALUES (?, ?, ?, ?, ?, ?)', NEW.run, NEW.pos + 1, NEW.next, (CASE WHEN NEW.via = 1 THEN NEW.before ELSE NEW.gate END), (SELECT gate FROM seq WHERE run = NEW.run AND pos = NEW.pos + 2), 0 WHERE NEW.next IS NOT NULL AND (NEW.via = 1 OR NEW.had = 1);
  INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT NEW.run, 21, 1, NEW.next WHERE NEW.next IS NOT NULL AND NEW.via = 0 AND NEW.had = 0;
  INSERT INTO hop (text, p1, p2, p3, p4, p5, p6) SELECT 'INSERT INTO main.land (run, pos, gate, before, next, via) VALUES (?, ?, ?, ?, ?, ?)', NEW.run, NEW.pos, 16, NEW.gate, NEW.next, 1 WHERE NEW.next IS NOT NULL AND NEW.via = 0 AND NEW.had = 0;
  INSERT INTO hop (text, p1, p2, p3) SELECT 'INSERT INTO main.replay (parent, source, kind) VALUES (?, ?, ?)', NEW.run, NEW.spawn, 2 WHERE NEW.spawn IS NOT NULL;
  INSERT INTO hop (text, p1, p2, p3) SELECT 'INSERT INTO main.replay (parent, source, kind) VALUES (?, ?, ?)', NEW.run, NEW.call, 1 WHERE NEW.call IS NOT NULL;
  INSERT INTO build_span (run, pos) SELECT NEW.run, NEW.pos WHERE NEW.gate = 29 AND NEW.via = 0 AND NOT EXISTS (SELECT 1 FROM build_span WHERE run = NEW.run);
  DELETE FROM build_span WHERE run = NEW.run AND NEW.gate = 29 AND NEW.via = 0 AND NEW.pos > pos AND EXISTS (SELECT 1 FROM build_span WHERE run = NEW.run AND pos < NEW.pos);
  INSERT INTO out_mother (run, cell, gate, at, text) SELECT NEW.run, 22, 29, (SELECT at FROM run WHERE id = NEW.run), (SELECT group_concat(piece, '') FROM (SELECT coalesce((SELECT value FROM run_sheet WHERE run = NEW.run AND cell = s.gate AND state = 1), (SELECT value FROM run_sheet WHERE run = (SELECT parent FROM run WHERE id = NEW.run) AND cell = s.gate AND state = 1), (SELECT value FROM run_sheet WHERE run = (SELECT parent FROM run WHERE id = (SELECT parent FROM run WHERE id = NEW.run)) AND cell = s.gate AND state = 1), l.symbol) AS piece FROM seq s JOIN label l ON l.gate = s.gate WHERE s.run = NEW.run AND s.pos > b.pos AND s.pos < NEW.pos ORDER BY s.pos)) FROM (SELECT pos FROM (SELECT max(r.pos) AS pos FROM run_receipt r WHERE r.run = NEW.run AND r.gate = 29 AND r.pos < NEW.pos)) b WHERE NEW.gate = 29 AND NEW.via = 0 AND b.pos IS NOT NULL AND NOT EXISTS (SELECT 1 FROM build_span WHERE run = NEW.run);
END;
CREATE TRIGGER out_mother_go AFTER INSERT ON out_mother BEGIN
  INSERT INTO secondary (run, cell, gate, about, text) VALUES (NEW.run, NEW.cell, 4, NULL, mother(NEW.text));
  UPDATE out_mother SET text = NULL WHERE id = NEW.id;
END;
CREATE TRIGGER ended_go AFTER INSERT ON ended BEGIN
  INSERT INTO run_memory (run, input, source, gate, shard, at) VALUES (NEW.run, coalesce((SELECT group_concat(gate, ' ') FROM (SELECT gate FROM seq WHERE run = NEW.run ORDER BY pos)), ''), (SELECT arrival FROM run WHERE id = NEW.run), NEW.gate, NEW.shard, (SELECT at FROM run WHERE id = NEW.run));
  INSERT OR REPLACE INTO run_sheet (run, cell, state, value) SELECT parent, cell, 1, NEW.run FROM run WHERE id = NEW.run AND cell IS NOT NULL AND parent IS NOT NULL;
  SELECT mother('INSERT INTO main."' || about || '.node" (source, run) VALUES (?, ?)', arrival, NEW.run) FROM run WHERE id = NEW.run AND about IS NOT NULL;
  INSERT OR IGNORE INTO complete (run) SELECT NEW.run WHERE NOT EXISTS (SELECT 1 FROM run_sheet WHERE run = NEW.run AND state = 0);
END;
CREATE TRIGGER memory_go AFTER INSERT ON run_memory BEGIN
  INSERT INTO timeline (at, run, key1, key2) VALUES (NEW.at, NEW.run, (SELECT gate FROM seq WHERE run = NEW.run AND pos = 1), (SELECT gate FROM seq WHERE run = NEW.run ORDER BY pos DESC LIMIT 1));
  SELECT mother('INSERT INTO sixth.third (text) VALUES (?)', 'seen : ' || NEW.run) WHERE (SELECT kind FROM run WHERE id = NEW.run) = 0;
END;
CREATE TRIGGER sheet_fill AFTER INSERT ON run_sheet WHEN NEW.state = 1 BEGIN
  INSERT OR IGNORE INTO complete (run) SELECT NEW.run WHERE EXISTS (SELECT 1 FROM run_memory WHERE run = NEW.run) AND NOT EXISTS (SELECT 1 FROM run_sheet WHERE run = NEW.run AND state = 0);
END;
CREATE TRIGGER complete_go AFTER INSERT ON complete BEGIN
  INSERT INTO out_user (run, cell, value) SELECT run, cell, value FROM run_sheet WHERE run = NEW.run AND (SELECT kind FROM run WHERE id = NEW.run) = 0 ORDER BY cell;
END;
